red_logo_storage_session_closed()","volatility":"v"}]}'::jsonb;operation text:='apply';wanted jsonb;actual jsonb;helper jsonb;p pg_catalog.pg_proc;
 helper_before jsonb;policy_before jsonb;helper_after jsonb;policy_after jsonb;roles_before jsonb;roles_after jsonb;
BEGIN
 IF session_user<>'postgres'OR current_user<>'postgres'OR current_database()<>'postgres'
 OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
 OR NOT EXISTS(SELECT 1 FROM fluid_private.shared_storage_target t WHERE t.singleton AND t.origin='https://fricsfwqibyhemknqgyf.supabase.co')
 OR(SELECT count(*)FROM fluid_private.shared_storage_target)<>1 THEN RAISE EXCEPTION 'storage_metadata_operator_target';END IF;
 IF operation NOT IN('prepare','apply','resume')THEN RAISE EXCEPTION 'storage_metadata_mode';END IF;
 IF operation='apply'THEN LOCK TABLE storage.objects IN SHARE ROW EXCLUSIVE MODE;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('oid',r.oid,'row',to_jsonb(r))ORDER BY r.oid),'[]')INTO roles_before FROM pg_roles r;
 SELECT coalesce(jsonb_agg(jsonb_build_object('oid',q.oid,'owner',q.proowner,'acl',q.proacl,'src',q.prosrc,'config',q.proconfig,'definer',q.prosecdef,'language',q.prolang,'volatility',q.provolatile,'leakproof',q.proleakproof)ORDER BY q.oid),'[]')INTO helper_before FROM pg_proc q JOIN pg_namespace n ON n.oid=q.pronamespace WHERE n.nspname IN('public','fluid_private');
 SELECT coalesce(jsonb_agg(to_jsonb(q)ORDER BY q.oid),'[]')INTO policy_before FROM pg_policy q;
